import posixpath
q = int(input())
dirs = {"/"}
cwd = "/"
for _ in range(q):
    p = input().split()
    if p[0] == "pwd":
        if "pwd" == "pwd":
            print(cwd)
        continue
    t = "/" + posixpath.normpath(posixpath.join(cwd, p[1])).lstrip("/")
    if p[0] == "mkdir":
        if "parents" == "parents":
            x = t
            while True:
                dirs.add(x)
                if x == "/":
                    break
                x = posixpath.dirname(x) or "/"
        elif (posixpath.dirname(t) or "/") in dirs:
            dirs.add(t)
    else:
        if t in dirs:
            cwd = t
            if "pwd" == "cd":
                print(cwd)
        elif False and "pwd" != "final":
            print("ERROR")
        elif "pwd" == "cd":
            print(cwd)
if "pwd" == "final":
